  $$('.orderCheck').forEach(c=>c.onchange=()=>{c.checked?orderSelected.add(c.value):orderSelected.delete(c.value)});const hc=$('#orderHeaderCheck');if(hc){hc.checked=rows.length>0&&rows.every(o=>orderSelected.has(o.orderNo));hc.onchange=()=>{rows.forEach(o=>hc.checked?orderSelected.add(o.orderNo):orderSelected.delete(o.orderNo));renderOrders()}};
  $('#orderRangeText').textContent=orderTotal?`전체 ${orderTotal}건 / 현재 ${start+1}~${Math.min(start+rows.length,orderTotal)}건`:'전체 0건';let html='';if(pages>1){html+=`<button ${orderPage===1?'disabled':''} onclick="goOrderPage(${orderPage-1})">이전</button>`;for(let i=1;i<=pages;i++){if(pages>9&&Math.abs(i-orderPage)>3&&i!==1&&i!==pages){if(i===2||i===pages-1)html+='<span>…</span>';continue}html+=`<button class="${i===orderPage?'active':''}" onclick="goOrderPage(${i})">${i}</button>`}html+=`<button ${orderPage===pages?'disabled':''} onclick="goOrderPage(${orderPage+1})">다음</button>`}$('#orderPager').innerHTML=html;
