function renderAdminCart(){$('#aoCart').innerHTML=adminEdit.cart.map((x,i)=>`<div class="admin-item-row"><span class="item-no">${esc(x.productNo)}번</span><b>${esc(x.name)}</b><span>${esc(x.color)}</span><span>${esc(x.size)}</span><span>${x.qty}개</span><span>${money(x.price)}</span><strong>${money(x.price*x.qty)}</strong>${adminEdit.editMode?`<div class="qtybox"><button onclick="aoQty(${i},-1)">−</button><b>${x.qty}</b><button onclick="aoQty(${i},1)">+</button></div><button class="btn red mini" onclick="aoRemove(${i})">삭제</button>`:''}</div>`).join('')||'<div class="note">상품이 없습니다.</div>';$('#aoAmount').textContent=money(adminEdit.cart.reduce((s,x)=>s+x.price*x.qty,0))}
window.aoQty=(i,d)=>{adminEdit.cart[i].qty=Math.max(1,Number(adminEdit.cart[i].qty||1)+d);renderAdminCart()};window.aoRemove=i=>{adminEdit.cart.splice(i,1);renderAdminCart()};
function renderAdminCatalog(q){q=norm(q);const list=productCache.filter(p=>!q||norm(String(p.no)).includes(q)||norm(p.name).includes(q)).slice(0,40);$('#aoCatalog').innerHTML=list.map(p=>`<div class="admin-picker-row"><span>${esc(p.no)}번</span><b>${esc(p.name)}</b><span>${esc(p.color)}</span><span>${esc(p.size)}</span><span>${money(p.sale)}</span><small>주문가능 ${Number(p.availableQty??Math.max(0,Number(p.stock||0)-Number(p.orderQty||0)))}</small><button class="btn primary mini" onclick="aoAdd('${encodeURIComponent(p.no)}','${encodeURIComponent(p.color)}','${encodeURIComponent(p.size)}')">추가</button></div>`).join('')||'<div class="hint">검색 결과가 없습니다.</div>'}
window.aoAdd=(no,c,s)=>{no=decodeURIComponent(no);c=decodeURIComponent(c);s=decodeURIComponent(s);const p=productCache.find(x=>String(x.no)===String(no)&&x.color===c&&x.size===s);if(!p)return;const av=Number(p.availableQty??Math.max(0,Number(p.stock||0)-Number(p.orderQty||0))),old=adminEdit.order?.editItems?.find(y=>pkey(y)===pkey(p)),allow=av+Number(old?.qty||0);let x=adminEdit.cart.find(x=>pkey(x)===pkey(p));if((x?.qty||0)>=allow)return toast('주문가능수량은 '+allow+'개입니다.');if(x)x.qty++;else adminEdit.cart.push({productNo:p.no,name:p.name,color:p.color,size:p.size,qty:1,price:p.sale});renderAdminCart()};
async function saveAdminOrder(){if(adminEdit.order?.historyOnly)return toast('전체주문이력의 과거 주문은 조회만 가능합니다.');if(!adminEdit.order||!adminEdit.cart.length)return toast('주문상품을 확인해주세요.');try{busy(true);await api('admin_update_order',{orderNo:adminEdit.order.orderNo,receiver:$('#aoReceiver').value,zip:$('#aoZip').value,address:$('#aoAddress').value,memo:$('#aoMemo').value,items:adminEdit.cart});$('#orderModal').classList.remove('show');toast('수정했습니다.');loadOrders()}catch(e){toast(e.message)}finally{busy(false)}}
async function modalStatus(st){if(!adminEdit.order)return;await api('admin_update_status',{orderNos:[adminEdit.order.orderNo],status:st});$('#aoStatus').textContent=st;toast('변경했습니다.')}
async function modalDelete(){if(adminEdit.order?.historyOnly)return toast('전체주문이력의 과거 주문은 삭제하지 않습니다.');if(!adminEdit.order||!confirm('이 주문을 삭제할까요?'))return;await api('admin_delete_orders',{orderNos:[adminEdit.order.orderNo]});$('#orderModal').classList.remove('show');loadOrders()}

/* 빠른메뉴 */
async function rebuild3pl(){try{busy(true,'3PL을 고객주문 기준으로 새로 만들고 전체주문이력에 반영하는 중입니다...');const r=await api('admin_rebuild_3pl');toast('3PL '+r.rows+'건 생성 · 전체주문이력 동기화 완료');if($('#panel-lotte')?.classList.contains('active'))resetLotteResultView('3PL이 갱신되었습니다. 조회하기를 눌러 최신 목록을 확인하세요.')}catch(e){toast(e.message)}finally{busy(false)}}
async function rebuildSupplier(){try{busy(true,'고객주문 전체를 다시 읽어 거래처발주를 계산하는 중입니다...');const r=await api('admin_rebuild_supplier');toast(r.message||'거래처발주를 새로 계산했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
async function exportLotte(){if(typeof XLSX==='undefined')return;try{busy(true);const r=await api('admin_lotte_export'),ws=XLSX.utils.aoa_to_sheet([r.headers,...r.rows]),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'ALPS');XLSX.writeFile(wb,r.filename)}catch(e){toast(e.message)}finally{busy(false)}}
async function broadcastEnd(){try{busy(true,'라이브 종료 시각을 저장하고 있습니다...');const r=await api('admin_broadcast_end');toast(r.message||'라이브 종료 처리했습니다.');loadOrders()}catch(e){toast(e.message)}finally{busy(false)}}
async function combineSearch(){try{busy(true,'합배송 가능한 고객을 찾고 있습니다...');const r=await api('admin_combine_list',{from:$('#combineFrom').value,to:$('#combineTo').value,onlyEligible:$('#combineEligibleOnly').checked});combineCache=r.groups||[];$('#combineTbody').innerHTML=combineCache.map(g=>`<tr><td><input class="combineCheck" type="checkbox" value="${esc(g.key)}"></td><td><b>${esc(g.nickname)}</b></td><td>${esc(g.receiver)}</td><td>${g.orderCount}</td><td>${g.qty}</td><td><span class="pill ${g.allPaid?'green':'orange'}">${g.allPaid?'입금완료':'결제확인필요'}</span></td><td><details><summary>주문내용 보기</summary><pre class="detail-pre">${esc(g.itemsText||'')}</pre></details></td></tr>`).join('')||'<tr><td colspan="7">합배송 대상이 없습니다.</td></tr>';$('#combineCount').textContent='합배송 후보 '+combineCache.length+'명';$('#combineHeaderCheck').checked=false}catch(e){toast(e.message)}finally{busy(false)}}
async function combineCopy(){const t=combineCache.map(x=>x.nickname+' / '+x.receiver).join('\n');try{await navigator.clipboard.writeText(t);toast('복사했습니다.')}catch(e){}}
/* 카드결제 - 고객주문 카드결제대기 기준 */
function cardPillClass(s){return s==='발송완료'?'green':s==='재발송필요'?'red':'orange'}
function renderCards(){$('#cardTbody').innerHTML=(cardCache||[]).map(o=>{const sentMeta=o.lastSentAmount?`<div class="hint">최근 ${money(o.lastSentAmount)}${o.lastTaxExcluded?' · 부가세 제외':' · +10%'}</div>`:'',vip=o.vip&&o.vip.isVip?'<span class="pill vip-pill">VIP</span>':'';return`<tr><td><input type="checkbox" class="cardCheck" value="${esc(o.orderNos||o.orderNo)}"></td><td><b>${esc(o.displayOrderNo||o.orderNo)}</b>${o.qty?`<div class="hint">내품 ${Number(o.qty)}개</div>`:''}</td><td>${esc(o.nickname)} ${vip}</td><td>${esc(o.receiver)}</td><td>${esc(o.phone)}</td><td>${money(o.amount)}</td><td><b>${money(o.cardAmount)}</b>${o.vip?.taxExcluded?'<div class="hint">VIP 부가세 제외</div>':''}</td><td><span class="pill ${cardPillClass(o.cardStatus)}">${esc(o.cardStatus||'미발송')}</span>${o.sentAt?`<div class="hint">${esc(o.sentAt)}</div>`:''}${sentMeta}</td><td><select class="status-select ${statusClass(o.paymentStatus)}" onchange="cardStatusChange('${encodeURIComponent(o.orderNos||o.orderNo)}',this.value)"><option ${o.paymentStatus==='카드결제'?'selected':''}>카드결제</option><option ${o.paymentStatus==='카드결제대기'?'selected':''}>카드결제대기</option><option ${o.paymentStatus==='입금완료'?'selected':''}>입금완료</option></select></td></tr>`}).join('')||'<tr><td colspan="9">현재 카드결제 고객이 없습니다.</td></tr>';bindCardChecks()}
function updateCardFilterCounts(c={}){$('#cAll').textContent=c.all||0;$('#cUnsent').textContent=c.unsent||0;$('#cSent').textContent=c.sent||0;$('#cRelink').textContent=c.relink||0;$$('.card-send-filter').forEach(b=>b.classList.toggle('active',(b.dataset.cardSendFilter||'')===cardSendFilter))}
async function loadCards(mode='search',useWarm=false){const q=$('#cardQuery').value.trim();if(mode==='search'&&!q)return toast('검색어를 입력해주세요.');if(useWarm&&cardCache.length&&Date.now()-cardLoadedAt<20000){renderCards();setTimeout(()=>loadCards(mode,false),0);return}let shown=false,t=setTimeout(()=>{shown=true;busy(true,'카드결제 고객을 빠르게 조회하고 있습니다...')},450);try{const r=await api('admin_card_customers',{mode,query:q,sendStatus:cardSendFilter},30000);cardCache=r.orders||[];cardLoadedAt=Date.now();updateCardFilterCounts(r.counts||{});renderCards()}catch(e){toast(e.message)}finally{clearTimeout(t);if(shown)busy(false)}}
function bindCardChecks(){$$('.cardCheck').forEach(x=>x.onchange=updateCardSelectedCount);updateCardSelectedCount()}
function updateCardSelectedCount(){$('#cardSelectedCount').textContent='선택 '+$$('.cardCheck:checked').length+'명'}
async function sendCardLink(){const orderNos=$$('.cardCheck:checked').map(x=>x.value);if(!orderNos.length)return toast('고객을 선택해주세요.');const provider=$('#cardProvider').value,excludeTax=!!$('#cardTaxExclude')?.checked,modeText=excludeTax?'부가세 제외 · 주문금액 그대로':'부가세 10% 포함';if(!confirm(`선택 ${orderNos.length}명에게 ${modeText}으로 카드결제 링크를 생성할까요?`))return;const chunkSize=5,results=[],failures=[];try{busy(true,excludeTax?'부가세 제외 카드링크를 준비하고 있습니다...':'카드링크를 준비하고 있습니다...');for(let i=0;i<orderNos.length;i+=chunkSize){const batch=orderNos.slice(i,i+chunkSize);$('#busyText').textContent=(excludeTax?'부가세 제외 링크 생성 중 ':'카드링크 생성 중 ')+Math.min(i+batch.length,orderNos.length)+' / '+orderNos.length+'명';try{const r=await api('admin_card_link',{orderNos:batch,provider,excludeTax},45000);results.push(...(r.results||[]));failures.push(...(r.failures||[]))}catch(e){batch.forEach(no=>failures.push({orderNo:no,error:e.message||String(e)}))}}if(results.length){const text=results.map(x=>`${x.nickname||x.receiver} ${money(x.amount)}${x.taxExcluded?' (부가세 제외)':''}\n${x.link}`).join('\n\n');try{await navigator.clipboard.writeText(text);toast((excludeTax?'부가세 제외 ':'')+'카드결제 링크 '+results.length+'건을 생성하고 복사했습니다.')}catch(e){toast('링크 '+results.length+'건 생성 완료')}}if(failures.length)alert('실패 '+failures.length+'건\n\n'+failures.map(x=>x.orderNo+': '+x.error).join('\n'));await loadCards('all')}catch(e){toast(e.message)}finally{busy(false)}}
window.cardStatusChange=async(no,status)=>{try{await api('admin_update_status',{orderNos:decodeURIComponent(no).split(',').map(x=>x.trim()).filter(Boolean),status});toast('변경했습니다.');loadCards('all')}catch(e){toast(e.message)}};

/* 라이브 */
async function loadLive(){try{const r=await api('admin_live');$('#liveTbody').innerHTML=(r.rows||[]).map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.nickname)}</td><td>${esc(x.chat||x.text)}</td><td>${esc(x.productNo)}</td><td>${esc(x.color)}</td><td>${esc(x.size)}</td><td><select class="input compact-select" onchange="liveTypeChange(${Number(x.row||0)},this.value)"><option ${x.type==='예약'?'selected':''}>예약</option><option ${x.type==='대기'?'selected':''}>대기</option><option ${x.type==='취소'?'selected':''}>취소</option></select></td><td><span class="pill ${x.orderStatus==='작성완료'?'green':x.orderStatus==='취소'?'red':'gray'}">${esc(x.orderStatus||'미작성')}</span></td></tr>`).join('')||'<tr><td colspan="8">주문성 댓글이 없습니다.</td></tr>'}catch(e){toast(e.message)}}
window.liveTypeChange=async(row,type)=>{try{await api('admin_update_live',{rowNumber:row,type});toast(type+'로 변경했습니다.');await loadLive();if($('#panel-products')?.classList.contains('active'))loadProducts()}catch(e){toast(e.message)}};
async function broadcastStart(){ $('#startModal').classList.add('show') }
async function broadcastStartMode(mode){try{busy(true,mode==='new'?'상품정보까지 비우고 새 라이브를 시작합니다...':'현재 상품정보를 유지하고 새 라이브를 시작합니다...');const r=await api('admin_broadcast_start',{mode});toast(r.message||'라이브를 시작했습니다.');$('#startModal').classList.remove('show');productCache=[];loadLive()}catch(e){toast(e.message)}finally{busy(false)}}
async function collectLive(){try{busy(true,'주문성 댓글만 가져오는 중입니다...');const r=await api('admin_broadcast_collect');toast(r.message);loadLive()}catch(e){toast(e.message)}finally{busy(false)}}
async function saveLiveVideo(){try{await api('admin_settings_save',{settings:{youtubeVideoId:$('#liveVideoQuick').value}});toast('저장했습니다.');$('#liveLinkModal').classList.remove('show')}catch(e){toast(e.message)}}

/* 상품 */
async function loadProducts(){try{busy(true,'상품정보를 불러오고 있습니다...');const r=await api('admin_products');productCache=r.products||[];renderProducts()}catch(e){toast(e.message)}finally{busy(false)}}
function renderProducts(){$('#productTbody').innerHTML=productCache.map(p=>`<tr><td><input type="checkbox" class="productCheck" value="${encodeURIComponent(p.no)}|${encodeURIComponent(p.color)}|${encodeURIComponent(p.size)}"></td><td>${esc(p.no)}</td><td>${esc(p.name)}</td><td>${esc(p.color)}</td><td>${esc(p.size)}</td><td>${money(p.sale)}</td><td>${money(p.cost)}</td><td>${p.stock}</td><td><span class="pill ${p.status==='품절'?'red':'green'}">${esc(p.status)}</span></td><td>${p.commentReserveQty||0}</td><td>${p.orderQty||0}</td><td><b class="available-qty ${Number(p.availableQty||0)<=0?'soldout':''}">${Number(p.availableQty||0)}</b></td><td><button class="btn ghost" onclick="editProduct('${encodeURIComponent(p.no)}','${encodeURIComponent(p.color)}','${encodeURIComponent(p.size)}')">수정</button></td></tr>`).join('')||'<tr><td colspan="13">등록된 상품이 없습니다.</td></tr>'}
window.editProduct=(no,c,s)=>{no=decodeURIComponent(no);c=decodeURIComponent(c);s=decodeURIComponent(s);const p=productCache.find(x=>String(x.no)===String(no)&&x.color===c&&x.size===s);if(!p)return;$('#pNo').value=p.no;$('#pName').value=p.name;$('#pColor').value=p.color;$('#pSize').value=p.size;$('#pSale').value=p.sale;$('#pCost').value=p.cost;$('#pStock').value=p.stock;optionQueue=[];renderOptionQueue();window.scrollTo({top:0,behavior:'smooth'})};
function optionAdd(){const color=$('#pColor').value.trim(),size=$('#pSize').value.trim()||'FREE',stock=Number($('#pStock').value||0);if(!color)return toast('칼라를 입력해주세요.');optionQueue.push({color,size,stock});$('#pColor').value='';$('#pSize').value='FREE';renderOptionQueue()}
function renderOptionQueue(){$('#optionList').innerHTML=optionQueue.map((x,i)=>`<span class="pill">${esc(x.color)} / ${esc(x.size)} / 재고 ${x.stock} <button onclick="removeOption(${i})">×</button></span>`).join(' ')}window.removeOption=i=>{optionQueue.splice(i,1);renderOptionQueue()};
async function saveProduct(){const base={no:productCode($('#pNo').value),name:$('#pName').value,sale:$('#pSale').value,cost:$('#pCost').value},opts=optionQueue.length?optionQueue:[{color:$('#pColor').value,size:$('#pSize').value,stock:$('#pStock').value}];$('#pNo').value=base.no;if(!base.no||!base.name)return toast('상품번호와 상품명을 입력해주세요.');try{busy(true,'상품정보를 한 번에 저장하고 있습니다...');await api('admin_save_products',{products:opts.map(o=>({...base,...o}))},30000);clearProductForm();productCache=[];await loadProducts();toast('저장했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
function clearProductForm(){['pNo','pName','pColor','pSale','pCost','pStock'].forEach(id=>$('#'+id).value='');$('#pSize').value='FREE';optionQueue=[];renderOptionQueue()}
async function deleteProducts(){const keys=$$('.productCheck:checked').map(x=>x.value.split('|').map(decodeURIComponent)).map(x=>[x[0],norm(x[1]),norm(x[2])].join('|'));if(!keys.length)return toast('상품을 선택해주세요.');if(!confirm('선택 상품을 삭제할까요?'))return;await api('admin_delete_products',{keys});productCache=[];loadProducts()}
async function deleteAllProducts(){if(!confirm('등록된 상품정보를 모두 삭제할까요?\n과거 주문기록은 삭제되지 않습니다.'))return;await api('admin_delete_products',{all:true});productCache=[];loadProducts()}
async function saveSnapshot(){const vendor=$('#snapshotVendor').value.trim(),date=$('#snapshotDate').value||new Date().toISOString().slice(0,10);if(!vendor)return toast('업체명을 입력해주세요.');try{const r=await api('admin_snapshot_save',{date,vendorName:vendor});toast(r.count+'개 저장했습니다.');loadSnapshots()}catch(e){toast(e.message)}}
async function loadSnapshots(){try{const r=await api('admin_snapshot_list');$('#snapshotList').innerHTML=(r.snapshots||[]).map(x=>`<div class="cart-line"><div><b>${esc(x.date)} · ${esc(x.vendorName)}</b><div class="hint">${x.count}개</div></div><button class="btn softpink" onclick="loadSnapshot('${esc(x.date)}','${encodeURIComponent(x.vendorName)}')">불러오기</button></div>`).join('')||'<div class="hint">저장된 정보가 없습니다.</div>'}catch(e){}}
window.loadSnapshot=async(date,vendor)=>{if(!confirm(date+' 상품정보를 현재 상품정보로 불러올까요?'))return;await api('admin_snapshot_load',{date,vendorName:decodeURIComponent(vendor)});productCache=[];loadProducts()};async function loadSnapshotByDate(){const date=$('#snapshotDate').value;if(!date)return toast('날짜를 선택해주세요.');await api('admin_snapshot_load',{date});productCache=[];loadProducts()}

/* 사은품 */
async function loadGifts(){try{const r=await api('admin_gifts');giftCache=r.rules||[];$('#giftTbody').innerHTML=giftCache.map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.condition)}</td><td>${esc(x.gift)}</td><td><button class="btn red" onclick="deleteGift(${x.rowNumber})">삭제</button></td></tr>`).join('')||'<tr><td colspan="4">등록된 사은품이 없습니다.</td></tr>'}catch(e){toast(e.message)}}
async function saveGift(){await api('admin_save_gift',{type:$('#gType').value,condition:$('#gCondition').value,gift:$('#gGift').value});$('#gCondition').value='';$('#gGift').value='';loadGifts()}window.deleteGift=async r=>{await api('admin_delete_gift',{rowNumber:r});loadGifts()};async function applyGifts(){try{busy(true);const r=await api('admin_apply_gifts');toast('3PL '+r.rows+'건에 사은품 규칙을 적용했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}

/* 입금 */
function findBankHeaderRow(aoa){for(let i=0;i<Math.min(30,aoa.length);i++){const row=(aoa[i]||[]).map(x=>String(x||'').trim());if(row.includes('적요')&&row.includes('거래 금액'))return i;if(row.includes('입금자명')&&row.includes('입금금액'))return i}return-1}
async function bankUpload(file){bankPendingDeposits=[];bankSelectedFileName='';bankOriginalFile=file||null;bankPreviewHeaders=[];bankPreviewRows=[];$('#bankStart').disabled=true;if(!file||typeof XLSX==='undefined')return;try{const buf=await file.arrayBuffer(),wb=XLSX.read(buf,{cellDates:false}),ws=wb.Sheets[wb.SheetNames[0]],aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''}),hi=findBankHeaderRow(aoa);if(hi<0)throw new Error('거래내역 헤더(적요/거래 금액)를 찾지 못했습니다.');const h=aoa[hi].map(x=>String(x||'').trim()),nameI=h.indexOf('적요')>=0?h.indexOf('적요'):h.indexOf('입금자명'),amtI=h.indexOf('거래 금액')>=0?h.indexOf('거래 금액'):h.indexOf('입금금액'),typeI=h.indexOf('거래 유형');bankPreviewHeaders=h;bankPreviewRows=aoa.slice(hi+1).filter(r=>r.some(v=>String(v||'').trim()));renderBankPreview();bankCache=[];bankFilter='';bankPage=1;renderBank();bankPendingDeposits=aoa.slice(hi+1).filter(r=>typeI<0||String(r[typeI]||'').trim()==='입금').map(r=>({name:String(r[nameI]||'').replace(/^'+/,'').trim(),amount:Number(String(r[amtI]||'').replace(/[^0-9.-]/g,''))})).filter(x=>x.name&&Number.isFinite(x.amount)&&x.amount>0);bankSelectedFileName=file.name;$('#bankFileStatus').textContent=bankPendingDeposits.length?`${file.name} · 입금 ${bankPendingDeposits.length}건 준비됨`:`${file.name} · 매칭할 입금내역이 없습니다.`;$('#bankFileMeta').textContent=`업로드 ${new Date().toLocaleString('ko-KR')} · 원본 ${bankPreviewRows.length}행`;$('#bankStart').disabled=!bankPendingDeposits.length;if(bankPendingDeposits.length)await bankStartMatch()}catch(e){const msg=/password|encrypt|CFB|Unsupported|File is password/i.test(String(e&&e.message||e))?'암호가 설정된 엑셀입니다. 비밀번호를 해제한 뒤 다시 올려주세요.':(e.message||'파일을 다시 확인해주세요.');$('#bankFileStatus').textContent=msg;toast(msg)}}
async function bankStartMatch(){if(!bankPendingDeposits.length)return toast('먼저 거래내역 파일을 선택해주세요.');try{busy(true,'거래내역을 주문과 매칭하고 있습니다...');const r=await api('admin_bank_match',{deposits:bankPendingDeposits});bankCache=r.results||[];bankFilter='';bankPage=1;renderBank();switchBankTab('match');$('#bankFileStatus').textContent=`${bankSelectedFileName} · ${bankCache.length}건 매칭 완료`;toast('입금 대조를 완료했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
function bankCounts(){return{all:bankCache.length,paid:bankCache.filter(x=>x.status==='입금완료').length,missing:bankCache.filter(x=>x.status==='주문미발견').length,mismatch:bankCache.filter(x=>x.status==='금액불일치').length}}
function bankFilteredEntries(){return bankCache.map((x,i)=>({x,i})).filter(({x})=>!bankFilter||x.status===bankFilter)}
function bankPagerHtml(pages){if(pages<=1)return'';let html=`<button ${bankPage===1?'disabled':''} onclick="goBankPage(${bankPage-1})">이전</button>`;for(let i=1;i<=pages;i++){if(pages>11&&Math.abs(i-bankPage)>4&&i!==1&&i!==pages){if(i===2||i===pages-1)html+='<span>…</span>';continue}html+=`<button class="${i===bankPage?'active':''}" onclick="goBankPage(${i})">${i}</button>`}html+=`<button ${bankPage===pages?'disabled':''} onclick="goBankPage(${bankPage+1})">다음</button>`;return html}
function renderBank(){
  const c=bankCounts();$('#bankAllCount').textContent=c.all;$('#bankPaidCount').textContent=c.paid;$('#bankMissingCount').textContent=c.missing;$('#bankMismatchCount').textContent=c.mismatch;
  $$('.bank-filter').forEach(b=>b.classList.toggle('active',(b.dataset.bankFilter||'')===bankFilter));
  const arr=bankFilteredEntries(),total=arr.length,pages=Math.max(1,Math.ceil(total/bankPageSize));bankPage=Math.min(Math.max(1,bankPage),pages);const start=(bankPage-1)*bankPageSize,pageRows=arr.slice(start,start+bankPageSize);
  $('#bankResults').innerHTML=pageRows.map(({x,i})=>`<tr><td><input type="checkbox" class="bankCheck" value="${i}"></td><td><b>${esc(x.name)}</b></td><td>${money(x.amount)}</td><td><b>${esc(x.nickname||'-')}</b><div class="hint">${esc(x.receiver||'')}</div></td><td>${x.orderAmount?money(x.orderAmount):'-'}</td><td><span class="pill ${x.status==='입금완료'?'green':x.status==='금액불일치'?'red':'orange'}">${esc(x.status)}</span><div class="hint">${esc(x.reason||'')}</div>${x.orderNo?`<small>${esc(x.orderNo)}</small>`:''}</td><td>${(!x.orderNo&&x.candidates&&x.candidates.length)?`<select class="input bank-candidate" id="bankCandidate${i}"><option value="">후보 주문 선택</option>${x.candidates.map(c=>`<option value="${esc(c.no)}">${esc(c.no)} · ${esc(c.nickname||c.receiver)} · ${money(c.amount)}</option>`).join('')}</select>`:''}<select class="input" onchange="bankStatusChange(${i},this.value)" ${x.orderNo||(x.candidates&&x.candidates.length)?'':'disabled'}><option ${(x.paymentStatus||x.status)==='입금완료'?'selected':''}>입금완료</option><option ${x.paymentStatus==='미입금'?'selected':''}>미입금</option><option ${x.paymentStatus==='카드결제'?'selected':''}>카드결제</option><option ${x.paymentStatus==='카드결제대기'?'selected':''}>카드결제대기</option></select></td><td><button class="btn red mini" onclick="bankDeleteOne(${i})">삭제</button></td></tr>`).join('')||'<tr><td colspan="8">대조 결과가 없습니다.</td></tr>';
  $('#bankHeaderCheck').checked=false;
  if($('#bankRangeText'))$('#bankRangeText').textContent=total?`${bankFilter||'전체'} ${total}건 / 현재 ${start+1}~${Math.min(start+pageRows.length,total)}건 / 50건씩 보기`:`${bankFilter||'전체'} 0건 / 50건씩 보기`;
  if($('#bankPager'))$('#bankPager').innerHTML=bankPagerHtml(pages);
}
window.goBankPage=p=>{const next=Math.max(1,Number(p)||1);if(next===bankPage)return;bankPage=next;renderBank();const view=$('#bankMatchView');if(view)view.scrollIntoView({behavior:'smooth',block:'start'})};
window.bankStatusChange=async(i,status)=>{const x=bankCache[i];if(!x)return;let no=x.orderNo;if(!no){no=$('#bankCandidate'+i)?.value||'';if(!no)return toast('먼저 후보 주문을 선택해주세요.');x.orderNo=no;const c=(x.candidates||[]).find(v=>v.no===no);if(c)x.nickname=c.nickname||x.nickname;}try{await api('admin_bank_status',{orderNo:no,status});x.paymentStatus=status;if(status==='입금완료'){x.status='입금완료';x.reason=(x.reason||'')+' · 관리자 수동확인 완료';}renderBank();toast('변경했습니다.')}catch(e){toast(e.message)}};
window.bankDeleteOne=i=>{bankCache.splice(i,1);renderBank()};
function bankDeleteSelected(){const idx=$$('.bankCheck:checked').map(x=>Number(x.value)).filter(Number.isFinite).sort((a,b)=>b-a);if(!idx.length)return toast('삭제할 결과를 선택해주세요.');if(!confirm(idx.length+'건의 대조 결과를 목록에서 삭제할까요?\n고객주문 원본은 삭제되지 않습니다.'))return;idx.forEach(i=>bankCache.splice(i,1));renderBank();toast('선택한 결과를 삭제했습니다.')}
function bankReset(){bankCache=[];bankPendingDeposits=[];bankSelectedFileName='';bankFilter='';bankPage=1;bankOriginalFile=null;bankPreviewHeaders=[];bankPreviewRows=[];$('#bankFile').value='';$('#bankFileStatus').textContent='파일을 선택해주세요.';$('#bankFileMeta').textContent='';$('#bankStart').disabled=true;renderBank();renderBankPreview()}
/* 미출고 - 전체주문이력에서 송장번호가 없는 주문만 */
async function loadPending(){try{busy(true,'미출고 주문을 불러오는 중입니다...');const r=await api('admin_pending_list',{query:$('#pendingQuery')?.value||'',from:$('#pendingFrom')?.value||'',to:$('#pendingTo')?.value||'',status:$('#pendingStatus')?.value||'전체'});pendingCache=r.rows||[];renderPending()}catch(e){toast(e.message)}finally{busy(false)}}
function pendingItemPreview(x){const lines=(x.items||'').split('\n').filter(Boolean);return esc(lines.slice(0,2).join(' / '))+(lines.length>2?`<div class="hint">외 ${lines.length-2}줄</div>`:'')}
function renderPending(){const rows=pendingCache||[];$('#pendingTbody').innerHTML=rows.map(x=>`<tr><td><input class="pendingCheck" type="checkbox" value="${x.rowNumber}"></td><td><b>${esc(x.orderNo)}</b><div class="hint">${esc(x.date)}</div></td><td>${esc(x.nickname)}</td><td>${esc(x.receiver)}</td><td>${esc(x.phone)}</td><td class="pending-items">${pendingItemPreview(x)}<div class="hint">내품 ${x.qty||0}개</div></td><td><span class="pill ${statusClass(x.paymentStatus)}">${esc(x.paymentStatus)}</span></td><td><input id="pr${x.rowNumber}" class="input pending-reason-input" value="${esc(x.reason)}" placeholder="예: 거래처 입고 지연"></td><td><input id="pe${x.rowNumber}" class="input pending-date-input" type="date" value="${esc(x.expectedDate)}"></td><td><button class="btn primary mini" onclick="savePending(${x.rowNumber},'')">저장</button></td></tr>`).join('')||'<tr><td colspan="10">현재 미출고 주문이 없습니다.</td></tr>';$('#pendingCards').innerHTML='';if($('#pendingHeaderCheck'))$('#pendingHeaderCheck').checked=false}
window.savePending=async(row,prefix)=>{try{const pre=prefix||'',reason=$('#'+pre+'pr'+row)?.value||'',expectedDate=$('#'+pre+'pe'+row)?.value||'';await api('admin_pending_update',{rowNumber:row,reason,expectedDate});toast('미출고 정보를 저장했습니다.');await loadPending()}catch(e){toast(e.message)}};
function selectedPendingRows(){return [...new Set($$('.pendingCheck:checked').map(x=>Number(x.value)).filter(Number.isFinite))]}
function writeXlsx(r,sheetName='ALPS'){if(typeof XLSX==='undefined')return toast('엑셀 라이브러리를 불러오지 못했습니다.');const ws=XLSX.utils.aoa_to_sheet([r.headers,...r.rows]),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,sheetName);XLSX.writeFile(wb,r.filename)}
async function pendingLotte(){const rows=selectedPendingRows();if(!rows.length)return toast('다시 송장을 출력할 미출고 주문을 선택해주세요.');try{busy(true,'미출고 롯데택배 파일을 만드는 중입니다...');const r=await api('admin_pending_lotte_export',{rows});if(!r.rows?.length)return toast('출력 가능한 미출고 건이 없습니다.');writeXlsx(r);toast(r.rows.length+'줄의 롯데택배 파일을 만들었습니다.')}catch(e){toast(e.message)}finally{busy(false)}}

/* 롯데 송장 업로드 - V7.0.0 안전매칭 */
function findTrackingHeader(aoa){
  for(let i=0;i<Math.min(40,aoa.length);i++){
    const h=(aoa[i]||[]).map(x=>String(x||'').trim()),find=re=>h.findIndex(x=>re.test(x.replace(/\s+/g,'')));
    const oi=find(/^(주문번호|접수번호|고객주문번호|주문관리번호)$/),ti=find(/^(운송장번호|송장번호|택배운송장번호)$/),ri=find(/^(받는사람|받는분|받는사람명|수령인|수취인|수취인명|수하인|수하인명|수화주)$/),pi=find(/^(전화번호1|전화번호|연락처|휴대폰|휴대전화|휴대전화번호|핸드폰|핸드폰번호|수령인연락처|수취인연락처|수하인전화번호)$/);
    if(ti>=0&&(oi>=0||(ri>=0&&pi>=0)))return{i,oi,ti,ri,pi};
  }
  return null;
}
function resetTrackingCounts(total=0){$('#trackMatched').textContent='0';$('#trackDuplicate').textContent='0';$('#trackReview').textContent='0';$('#trackMissing').textContent='0';$('#trackTotal').textContent=String(total||0)}
function trackingPhoneText(v){let s=String(v??'').trim(),d=s.replace(/\D/g,'');if(d.length===10&&d.startsWith('10'))d='0'+d;return d||s}
async function trackingRead(file){
  trackingRows=[];$('#trackingTbody').innerHTML='';resetTrackingCounts(0);if(!file)return;
  try{
    const buf=await file.arrayBuffer(),wb=XLSX.read(buf,{cellDates:false}),ws=wb.Sheets[wb.SheetNames[0]],aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''}),h=findTrackingHeader(aoa);
    if(!h)throw new Error('송장번호 열과 주문번호 또는 수령인·연락처 열을 찾지 못했습니다.');
    trackingRows=aoa.slice(h.i+1).map((r,n)=>({rowNo:h.i+n+2,orderNo:h.oi>=0?String(r[h.oi]||'').trim():'',receiver:h.ri>=0?String(r[h.ri]||'').trim():'',phone:h.pi>=0?trackingPhoneText(r[h.pi]):'',tracking:String(r[h.ti]||'').replace(/[^0-9-]/g,'').trim(),result:'준비',matchMethod:'',matchedOrderNos:[],detail:''})).filter(x=>x.tracking&&(x.orderNo||(x.receiver&&x.phone)));
    $('#trackingStatus').textContent=`${file.name} · ${trackingRows.length}건 준비됨 · 수령인/연락처 ${h.ri>=0&&h.pi>=0?'확인 가능':'열 없음'}`;resetTrackingCounts(trackingRows.length);renderTrackingRows();
  }catch(e){trackingRows=[];resetTrackingCounts(0);$('#trackingStatus').textContent=e.message;toast(e.message)}
}
async function trackingApply(){
  if(!trackingRows.length)return toast('먼저 롯데 송장 결과 엑셀을 선택해주세요.');
  try{
    busy(true,'송장번호를 안전하게 대조하고 있습니다...');
    const r=await api('admin_apply_tracking',{items:trackingRows},60000),c=r.counts||{};trackingRows=r.results||trackingRows;
    $('#trackMatched').textContent=c.matched||0;$('#trackDuplicate').textContent=c.duplicate||0;$('#trackReview').textContent=c.review||0;$('#trackMissing').textContent=c.unmatched||0;$('#trackTotal').textContent=c.total??trackingRows.length;
    $('#trackingStatus').textContent=`매칭완료 ${c.matched||0} · 중복 ${c.duplicate||0} · 확인필요 ${c.review||0} · 미매칭 ${c.unmatched||0} · 실제 갱신 ${r.updated||0}행`;
    renderTrackingRows();toast(`송장번호 대조 완료 · 매칭 ${c.matched||0}건`);
  }catch(e){toast(e.message)}finally{busy(false)}
}
/* 배송비 / VIP */
async function loadShippingPolicy(){try{const r=await api('admin_shipping_policy',{},30000),on=!!r.freeShippingEvent;shippingLoaded=true;$('#shippingPolicyBadge').textContent=on?'무료배송 이벤트 적용중':'기본 배송비 정책';$('#shippingPolicyBadge').className='pill '+(on?'green':'blue');$('#shipBasic').value=Number(r.shipping||4000);$('#shipIsland').value=Number(r.islandShipping||7000);$('#shipThreshold').value=Number(r.freeShippingThreshold||200000);$('#shipCardRate').value=String(Number(r.cardExtraRate??0.10));$('#shipFreeEvent').checked=on;$('#shippingPolicyBox').innerHTML=on?'<strong>🚚 무료배송 이벤트 적용중</strong><br><span>현재 주문과 새 주문의 배송비가 0원입니다. VIP 개별 혜택도 계속 유지됩니다.</span>':`<strong>기본 정책 사용중</strong><br><span>${money(r.freeShippingThreshold||200000)} 이상 무료 · 일반 ${money(r.shipping||4000)} · 제주/도서산간 ${money(r.islandShipping||7000)} · VIP ${Number(r.vipCount||0)}명</span>`}catch(e){toast(e.message)}}
async function saveShippingSettings(){if(!shippingLoaded)return toast('먼저 설정 불러오기를 눌러 현재 배송비 설정을 확인해주세요.');const payload={shipping:Number($('#shipBasic').value||0),islandShipping:Number($('#shipIsland').value||0),freeShippingThreshold:Number($('#shipThreshold').value||0),cardExtraRate:Number($('#shipCardRate').value||0),freeShippingEvent:$('#shipFreeEvent').checked};if(!confirm('배송비/VIP 기본 정책을 저장하고 현재 고객주문 금액을 다시 계산할까요?'))return;try{busy(true,'배송비 정책을 저장하고 주문금액을 다시 계산하고 있습니다...');const r=await api('admin_shipping_settings_save',payload,60000);await loadShippingPolicy();toast(`배송비 설정 저장 완료 · ${Number(r.changed||0)}건 금액 갱신${Number(r.relink||0)?` · 카드링크 재발송필요 ${Number(r.relink)}건`:''}`)}catch(e){toast(e.message)}finally{busy(false)}}
async function applyShippingEvent(free){$('#shipFreeEvent').checked=!!free;return saveShippingSettings()}
function renderVip(){const q=norm($('#vipQuery')?.value||''),rows=vipCache.filter(x=>!q||[x.nickname,x.receiver,x.phone,x.memo].some(v=>norm(v).includes(q)));$('#vipTbody').innerHTML=rows.map((x,i)=>`<tr><td><input type="checkbox" class="vipCheck" value="${x.rowNumber}"></td><td>${i+1}</td><td><b>${esc(x.nickname)}</b></td><td>${esc(x.receiver)}</td><td>${esc(x.phone)}</td><td><span class="pill ${x.taxExcluded?'green':'red'}">${x.taxExcluded?'제외':'적용'}</span></td><td><span class="pill ${x.freeShipping?'green':'orange'}">${x.freeShipping?'무료':'기본'}</span></td><td><span class="pill ${x.active?'blue':'gray'}">${x.active?'사용중':'중지'}</span></td><td><div class="mini-actions"><button class="btn ghost mini" onclick="editVip(${x.rowNumber})">수정</button><button class="btn red mini" onclick="deleteVipOne(${x.rowNumber})">삭제</button></div></td></tr>`).join('')||'<tr><td colspan="9">등록된 VIP 고객이 없습니다.</td></tr>';$('#vipCount').textContent=`전체 ${vipCache.length}명 · 현재 ${rows.length}명`;$('#vipHeaderCheck').checked=false}
async function loadVip(query=''){try{const r=await api('admin_vip_list',{query},30000);vipCache=r.rows||[];renderVip()}catch(e){toast(e.message)}}
function openVip(row=0){const x=vipCache.find(v=>v.rowNumber===Number(row))||{};$('#vipRow').value=x.rowNumber||'';$('#vipNickname').value=x.nickname||'';$('#vipReceiver').value=x.receiver||'';$('#vipPhone').value=x.phone||'';$('#vipTax').value=x.taxExcluded===false?'0':'1';$('#vipShipping').value=x.freeShipping===false?'0':'1';$('#vipActive').value=x.active===false?'0':'1';$('#vipMemo').value=x.memo||'';$('#vipModal').classList.add('show')}
window.editVip=row=>openVip(row);
async function saveVip(){try{busy(true,'VIP 고객을 저장하고 주문금액을 다시 확인하고 있습니다...');await api('admin_vip_save',{rowNumber:$('#vipRow').value,nickname:$('#vipNickname').value,receiver:$('#vipReceiver').value,phone:$('#vipPhone').value,taxExcluded:$('#vipTax').value==='1',freeShipping:$('#vipShipping').value==='1',active:$('#vipActive').value==='1',memo:$('#vipMemo').value},60000);$('#vipModal').classList.remove('show');await loadVip();await loadShippingPolicy();toast('VIP 고객을 저장했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
async function deleteVipRows(rows){if(!rows.length)return toast('삭제할 VIP 고객을 선택해주세요.');if(!confirm(rows.length+'명의 VIP 등록을 삭제할까요?'))return;try{busy(true,'VIP 목록을 정리하고 있습니다...');await api('admin_vip_delete',{rows},60000);await loadVip();await loadShippingPolicy();toast('삭제했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
