async function loadLotteOrders(extra={}){
  try{
    prepareLottePanel();if(!validateLotteDates())return;
    if(Object.prototype.hasOwnProperty.call(extra,'page'))lottePage=Math.max(1,Number(extra.page)||1);else lottePage=1;
    busy(true,'전체주문이력에서 선택한 날짜의 주문을 50건씩 불러오고 있습니다...');
    const r=await api('admin_lotte_history_list',{...lotteParams(),page:lottePage,pageSize:lottePageSize},45000);
    lotteCache=r.rows||[];lotteTotal=Number(r.total||0);lottePage=Number(r.page||lottePage||1);lotteLoaded=true;lotteCounts=r.counts||{all:0,paid:0,unpaid:0,cardPending:0};
    $('#lAll').textContent=lotteCounts.all||0;$('#lPaid').textContent=lotteCounts.paid||0;$('#lWaiting').textContent=(Number(lotteCounts.unpaid||0)+Number(lotteCounts.cardPending||0));
    $$('[data-lotte-status]').forEach(b=>b.classList.toggle('active',b.dataset.lotteStatus===$('#lotteStatus').value));
    $('#lotteSummary').innerHTML=`${esc($('#lotteFrom').value)} ~ ${esc($('#lotteTo').value)} &nbsp; <b>총 ${Number(lotteCounts.all||0)}건</b> &nbsp; | &nbsp; 입금완료 ${Number(lotteCounts.paid||0)}건 &nbsp; | &nbsp; 미입금 ${Number(lotteCounts.unpaid||0)}건 &nbsp; | &nbsp; 카드결제대기 ${Number(lotteCounts.cardPending||0)}건`;
    renderLotteRows();
  }catch(e){toast(e.message)}finally{busy(false)}
}
function renderLotteRows(){
  const rows=lotteCache||[],pages=Math.max(1,Math.ceil(lotteTotal/lottePageSize));lottePage=Math.min(lottePage,pages);const start=(lottePage-1)*lottePageSize;
  $('#lotteTbody').innerHTML=rows.map((x,i)=>`<tr><td><input class="lotteCheck" type="checkbox" value="${esc(x.orderNo)}" ${lotteSelected.has(x.orderNo)?'checked':''}></td><td>${start+i+1}</td><td>${esc(x.date)}</td><td><b>${esc(x.orderNo)}</b></td><td>${esc(x.nickname)}</td><td>${esc(x.receiver)}</td><td>${esc(x.phone)}</td><td><b>${Number(x.qty||0)}</b></td><td><span class="pill ${statusClass(x.status)}">${esc(x.status)}</span></td><td><div class="lotte-items-cell" title="${esc(x.items||'')}">${esc((x.items||'').replace(/\n/g,' · '))}</div></td><td>${esc(x.tracking||'-')}</td></tr>`).join('')||'<tr><td colspan="11">조건에 맞는 주문이 없습니다.</td></tr>';
  $$('.lotteCheck').forEach(c=>c.onchange=()=>{c.checked?lotteSelected.add(c.value):lotteSelected.delete(c.value);updateLotteHeaderCheck();updateLotteRangeText()});
  updateLotteHeaderCheck();updateLotteRangeText();
  let html='';if(pages>1){html+=`<button ${lottePage===1?'disabled':''} onclick="goLottePage(${lottePage-1})">‹</button>`;for(let i=1;i<=pages;i++){if(pages>11&&Math.abs(i-lottePage)>4&&i!==1&&i!==pages){if(i===2||i===pages-1)html+='<span>…</span>';continue}html+=`<button class="${i===lottePage?'active':''}" onclick="goLottePage(${i})">${i}</button>`}html+=`<button ${lottePage===pages?'disabled':''} onclick="goLottePage(${lottePage+1})">›</button>`}$('#lottePager').innerHTML=html;
}
function updateLotteRangeText(){const rows=lotteCache||[],start=(lottePage-1)*lottePageSize;$('#lotteRangeText').textContent=lotteTotal?`총 ${lotteTotal}건 중 ${start+1}~${Math.min(start+rows.length,lotteTotal)}건 표시 · 선택 ${lotteSelected.size}건`:'전체 0건'}
function updateLotteHeaderCheck(){const checks=$$('.lotteCheck'),h=$('#lotteHeaderCheck');if(!h)return;h.disabled=!checks.length;h.checked=checks.length>0&&checks.every(x=>lotteSelected.has(x.value))}
